.card {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  padding: 0;
  scroll-margin: 6px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--back);
  color: var(--text);
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
  transition: border-color 120ms ease;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.card:hover {
  border-color: var(--text);
}
.card.revealed,
.card.matched {
  background: var(--face);
}
.card.matched {
  border-color: var(--green);
}
.card > svg {
  display: block;
  width: 100%;
  height: 100%;
}
.card-back {
  width: 12px;
  height: 12px;
  border: 2px solid var(--secondary);
  transform: rotate(45deg);
}
/* A corner mark wider than about 17% of the card would reach the top-right marker. */
.card > .matched-mark {
  position: absolute;
  right: 0;
  top: 0;
  width: 16%;
  height: 16%;
  color: var(--green);
}
.stats {
  display: flex;
  flex-wrap: wrap;
